"""Independent exact checker for the 120-line E8 Grothendieck certificate.

This implementation deliberately differs from e8_certificate_checker.py:

* roots are generated by Weyl-reflection closure in simple-root coordinates;
* upper filters are enumerated through their unique antichains;
* the Bell matrix, tight-frame identity, exceptional envelope, and an explicit
  A1+A6 equality witness are checked in one exact-integer computation.

No floating-point arithmetic or optimization solver is used.
"""

from fractions import Fraction


C = (
    (2, 0, -1, 0, 0, 0, 0, 0),
    (0, 2, 0, -1, 0, 0, 0, 0),
    (-1, 0, 2, -1, 0, 0, 0, 0),
    (0, -1, -1, 2, -1, 0, 0, 0),
    (0, 0, 0, -1, 2, -1, 0, 0),
    (0, 0, 0, 0, -1, 2, -1, 0),
    (0, 0, 0, 0, 0, -1, 2, -1),
    (0, 0, 0, 0, 0, 0, -1, 2),
)

SIMPLE_AMBIENT = (
    tuple(Fraction(x, 2) for x in (1, -1, -1, -1, -1, -1, -1, 1)),
    tuple(map(Fraction, (1, 1, 0, 0, 0, 0, 0, 0))),
    tuple(map(Fraction, (-1, 1, 0, 0, 0, 0, 0, 0))),
    tuple(map(Fraction, (0, -1, 1, 0, 0, 0, 0, 0))),
    tuple(map(Fraction, (0, 0, -1, 1, 0, 0, 0, 0))),
    tuple(map(Fraction, (0, 0, 0, -1, 1, 0, 0, 0))),
    tuple(map(Fraction, (0, 0, 0, 0, -1, 1, 0, 0))),
    tuple(map(Fraction, (0, 0, 0, 0, 0, -1, 1, 0))),
)

EXPECTED_F = (
    0, 2, 6, 12, 20, 30, 42, 56, 72, 86, 104, 124, 146, 170, 196, 212,
    230, 250, 272, 300, 322, 350, 372, 402, 430, 460, 492, 526, 562, 600,
    622, 646, 672, 700, 730, 762, 800, 826, 862, 900, 932, 966, 1004, 1044,
    1086, 1130, 1166, 1204, 1244, 1286, 1332, 1376, 1422, 1470, 1520, 1572,
    1626, 1682, 1684, 1688, 1694, 1702, 1712, 1724, 1738, 1748, 1764, 1782,
    1794, 1808, 1824, 1850, 1882, 1916, 1952, 1990, 2030, 2072, 2116, 2118,
    2122, 2128, 2136, 2166, 2168, 2172, 2184, 2200, 2218, 2238, 2260, 2280,
    2312, 2314, 2318, 2324, 2332, 2352, 2366, 2368, 2372, 2378, 2386, 2400,
    2420, 2422, 2430, 2432, 2440, 2442, 2450, 2452, 2460, 2462, 2466, 2468,
    2472, 2474, 2476, 2478, 2480,
)


def qform(x, y):
    return sum(x[i] * C[i][j] * y[j] for i in range(8) for j in range(8))


def reflect(x, i):
    """Simple reflection s_i(x)=x-(x,alpha_i)alpha_i."""
    pairing = sum(C[i][j] * x[j] for j in range(8))
    y = list(x)
    y[i] -= pairing
    return tuple(y)


def generate_roots():
    roots = set()
    frontier = []
    for i in range(8):
        e = tuple(1 if i == j else 0 for j in range(8))
        roots.add(e)
        frontier.append(e)
    while frontier:
        x = frontier.pop()
        for i in range(8):
            y = reflect(x, i)
            if y not in roots:
                roots.add(y)
                frontier.append(y)
    return roots


def add_vectors(vectors):
    return tuple(sum(v[i] for v in vectors) for i in range(8))


def ambient(x):
    return tuple(sum(x[i] * SIMPLE_AMBIENT[i][j] for i in range(8)) for j in range(8))


def gram(rows):
    return [[qform(x, y) for y in rows] for x in rows]


roots = generate_roots()
assert len(roots) == 240
assert all(qform(r, r) == 2 for r in roots)
assert all(tuple(-a for a in r) in roots for r in roots)

pos = sorted(r for r in roots if all(a >= 0 for a in r))
assert len(pos) == 120
assert all(r == (0,) * 8 or any(a > 0 for a in r) for r in pos)

# Verify the line representatives form the exact E8 tight frame.
ambient_pos = [ambient(r) for r in pos]
frame = [
    [sum(r[i] * r[j] for r in ambient_pos) for j in range(8)]
    for i in range(8)
]
assert frame == [[Fraction(30 if i == j else 0) for j in range(8)] for i in range(8)]

G = gram(pos)
assert all(G[i][i] == 2 for i in range(120))
assert all(G[i][j] in (-1, 0, 1) for i in range(120) for j in range(120) if i != j)
assert all(
    sum(G[i][k] * G[k][j] for k in range(120)) == 30 * G[i][j]
    for i in range(120)
    for j in range(120)
)
B = [[3 * G[i][j] - (13 if i == j else 0) for j in range(120)] for i in range(120)]
assert {B[i][i] for i in range(120)} == {-7}
assert {B[i][j] for i in range(120) for j in range(120) if i != j} == {-3, 0, 3}

# The root strategy u_i=r_i/sqrt(2) attains <B,G/2>=9240.
quantum_value_twice = sum(B[i][j] * G[i][j] for i in range(120) for j in range(120))
assert quantum_value_twice == 2 * 9240

# Build comparability and upper-closure masks.  Every upper filter is the
# upper closure of its unique antichain of minimal elements.
upper = []
comparable = []
for a in pos:
    up = 0
    comp = 0
    for j, b in enumerate(pos):
        a_le_b = all(x <= y for x, y in zip(a, b))
        b_le_a = all(y <= x for x, y in zip(a, b))
        if a_le_b:
            up |= 1 << j
        if a_le_b or b_le_a:
            comp |= 1 << j
    upper.append(up)
    comparable.append(comp)

F = [-1] * 121
antichain_count = 0


def record_antichain(mask):
    global antichain_count
    antichain_count += 1
    filt = 0
    todo = mask
    while todo:
        bit = todo & -todo
        i = bit.bit_length() - 1
        filt |= upper[i]
        todo ^= bit
    chosen = [pos[i] for i in range(120) if (filt >> i) & 1]
    z = add_vectors(chosen) if chosen else (0,) * 8
    k = len(chosen)
    F[k] = max(F[k], qform(z, z))


def enumerate_antichains(candidates, selected=0):
    if candidates == 0:
        record_antichain(selected)
        return
    bit = candidates & -candidates
    i = bit.bit_length() - 1
    enumerate_antichains(candidates ^ bit, selected)
    enumerate_antichains(candidates & ~comparable[i], selected | bit)


enumerate_antichains((1 << 120) - 1)
assert antichain_count == 25080
assert tuple(F) == EXPECTED_F
assert [
    (k, F[k], 3 * F[k] - 26 * k)
    for k in range(121)
    if 3 * F[k] - 26 * k > 4544
] == [(98, 2366, 4550), (104, 2420, 4556)]

# Exact A1+A6 equality witness.  Deleting alpha_3 (index 2) leaves the
# isolated alpha_1 and the A6 chain alpha_2,alpha_4,...,alpha_8.
parabolic = [r for r in pos if r[2] == 0]
complement = [r for r in pos if r[2] != 0]
assert len(parabolic) == 22
assert len(complement) == 98
p = add_vectors(complement)
omega3 = (7, 10, 14, 20, 16, 12, 8, 4)
assert tuple(sum(C[i][j] * omega3[j] for j in range(8)) for i in range(8)) == (0, 0, 1, 0, 0, 0, 0, 0)
assert p == tuple(13 * a for a in omega3)
assert qform(p, p) == 2366

chain = (1, 3, 4, 5, 6, 7)
a6_signed = []
sign_by_root = {}
for a in range(7):
    for b in range(a + 1, 7):
        root = [0] * 8
        for t in range(a, b):
            root[chain[t]] = 1
        root = tuple(root)
        sign = 1 if (b - a) % 7 in (1, 2, 3) else -1
        a6_signed.append(tuple(sign * x for x in root))
        sign_by_root[root] = sign
assert len(a6_signed) == 21
assert add_vectors(a6_signed) == (0,) * 8

alpha1 = (1, 0, 0, 0, 0, 0, 0, 0)
v = alpha1
assert qform(v, v) == 2

eps = []
eta = []
for r in pos:
    if r in complement:
        e = 1
        h = 1
    elif r == alpha1:
        e = 1
        h = -1
    else:
        e = sign_by_root[r]
        h = -e
    eps.append(e)
    eta.append(h)
assert sum(1 for e, h in zip(eps, eta) if e == h) == 98
classical_witness = sum(eps[i] * B[i][j] * eta[j] for i in range(120) for j in range(120))
assert classical_witness == 6104

# Script-checkable parts of the exceptional congruence closure.
assert 2366 % 4 == 2 and 2366 - 2 == 2364
assert 2418 % 4 == 2 and 2418 - 2 == 2416
assert 2420 % 8 == 4 and 2420 - 4 == 2416

print(f"roots, positive roots, antichains = {len(roots)} {len(pos)} {antichain_count}")
print("tight frame: RR^T = 30 I_8")
print("Bell matrix: B = 3 G - 13 I; B^2 relation checked through G^2 = 30 G")
print(f"vector value = {quantum_value_twice // 2}")
print(f"F_98, F_104 = {F[98]} {F[104]}")
print(f"A1+A6 witness: p^2={qform(p,p)} v^2={qform(v,v)} value={classical_witness}")
